INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (417663, 16393, 'Le Monde', 'en', 'Catastrophic floods kill over 390 in Nepal and Tibet, with more than 1,400 missing', 'https://www.lemonde.fr/en/environment/article/2026/08/26/nepal-floods-kill-at-least-19-people-with-hundreds-missing_6756872_114.html', 'A glacial collapse caused seismic activity and ''catastrophic'' downstream impacts in Nepal and Tibet on Wednesday. Officials said hundreds of tourists, including from countries such as India, the US, the UK and Malaysia, are still unaccounted for.', 'https://img.lemde.fr/2026/08/27/99/0/1194/597/644/322/60/0/fffe7e3_ftp-1-4jsvz63rmy14-c647284a110f41488cac5ac925042978-1-8d0267b6c4b640d4b57ecbc0a6c6d426.jpg', '2026-08-26T13:02:32+00:00', '2026-08-28T00:05:24.755145'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (417664, 16393, 'Le Monde', 'en', 'Floods in Nepal and Tibet: ''The disaster began with a landslide that swept a glacier along with it''', 'https://www.lemonde.fr/en/environment/article/2026/08/27/floods-in-nepal-and-tibet-the-disaster-began-with-a-landslide-that-swept-a-glacier-along-with-it_6756915_114.html', 'While the exact volume of rock and ice that broke away in the Himalayas has yet to be measured, this catastrophe is already of exceptional magnitude, explains glaciologist Adrien Gilbert in an interview with Le Monde.', 'https://img.lemde.fr/2026/08/27/18/0/6912/3456/644/322/60/0/87d4585_ftp-1-tu0aucmhrryu-5927939-01-06.jpg', '2026-08-27T21:55:20+00:00', '2026-08-28T00:05:24.769106'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (417679, 16393, 'Le Monde', 'en', 'In Nepal and Tibet, floods triggered by ice-rock avalanche bring devastation', 'https://www.lemonde.fr/en/environment/article/2026/08/27/in-nepal-and-tibet-floods-triggered-by-ice-rock-avalanche-bring-devastation_6756898_114.html', 'Floods and mudslides of unprecedented violence, brought on by the collapse of a high-altitude glacier, have buried villages and roads, killing at least 180 people and leaving more than 1,300 missing as of Thursday. The affected region is popular with trekkers and Hindu pilgrims.', 'https://img.lemde.fr/2026/08/27/285/0/8025/4012/644/322/60/0/00c8abf_ftp-1-lmxcjaiashbg-2026-08-27t020731z-574437780-rc2p6naphnwt-rtrmadp-3-nepal-floods.JPG', '2026-08-27T08:56:24+00:00', '2026-08-28T00:05:24.927285'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
