INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (417863, 16393, 'NBC News', 'en', 'Drone video shows aftermath of deadly floods in Nepal', 'https://www.nbcnews.com/video/drone-video-shows-aftermath-of-deadly-floods-in-nepal-268960837563', 'Deadly flash flooding and mudslides left villages near the Nepal-Tibet border devastated. More than 1,400 people remain missing after the floods, including 65 Americans.', 'https://prodamdnewsencoding.akamaized.net/NBC_News_Digital/f_mo_nepal_aftermath_drone_260827/1/abs/index.m3u8', '2026-08-27T19:03:45+00:00', '2026-08-28T00:05:54.344311'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (417864, 16393, 'NBC News', 'en', 'Families await news of missing loves ones after catastrophic floods', 'https://www.nbcnews.com/video/families-await-news-of-missing-loves-ones-after-catastrophic-floods-in-nepal-268936261817', 'Relatives of people missing in devastating floods along the border of Nepal and China waited outside a Kathmandu hospital, desperate for news of loved ones. "All I want is that my husband comes back to me safely in one piece. I do not want anything else," said Subina Tamang, one of many relatives who crowded the hospital to register the names of loved ones still unaccounted for.', 'https://prodamdnewsencoding.akamaized.net/NBC_News_Digital/f_mo_lon_nepal_families_260827/1/abs/index.m3u8', '2026-08-27T10:35:32+00:00', '2026-08-28T00:05:54.461571'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
